#include <iostream>
#include <fstream>
class FileOpener {
public:
  FileOpener(const std::string& filename) : file(filename) {
    if (!file.is_open()) {
      throw std::runtime_error("Could not open file!");
    }
  }
  ~FileOpener() { file.close(); }
  std::fstream& getFile() { return file; }
private:
  std::fstream file;
};
int main() {
  try {
    FileOpener myFile("example.txt");
    myFile.getFile() << "This text will be written to the file.";
  } catch (const std::runtime_error& error) {
    std::cerr << "Error: " << error.what() << std::endl;
    return 1;
  }
  return 0;
}
